// Audits the live CRM sheet and returns ONLY aggregates.
try {
  var res = $input.first().json;
  var rows = res.values || [];
  if (!rows.length) { return [{ json: { _error: 'No rows returned', raw: res } }]; }

  var header = rows[0];
  var body = rows.slice(1);

  function idx(name) { return header.indexOf(name); }
  var iName = idx('Company Name'), iPhone = idx('Phone'), iEmail = idx('Email');
  var iRoute = idx('Template Route'), iPrio = idx('Priority'), iSrc = idx('Source');
  var iEmailable = idx('Emailable'), iDate = idx('Date Added'), iTrade = idx('Trade');
  var iScene = idx('Trade Scene'), iCert = idx('MCS Cert Number'), iVer = idx('Email Verify Status');
  var iCountry = idx('UK Country'), iComp = idx('Top Competitor'), iPecr = idx('PECR Risk');

  var seenPhone = {}, seenCert = {};
  var dupPhone = 0, dupCert = 0, dupPhoneEg = [], dupCertEg = [];
  var blankName = 0, blankPhone = 0, blankEmail = 0, blankTrade = 0, blankScene = 0;
  var routes = {}, prios = {}, srcs = {}, dates = {}, countries = {}, vers = {};
  var emailableY = 0, pecrY = 0, withComp = 0, shortRows = 0, longRows = 0;
  var genericScene = 0, genericTrade = 0;

  function bump(o, k) { var key = (k === undefined || k === '') ? '(blank)' : String(k); o[key] = (o[key] || 0) + 1; }

  for (var i = 0; i < body.length; i++) {
    var r = body[i];
    if (r.length < header.length) { shortRows++; }
    if (r.length > header.length) { longRows++; }

    var nm = r[iName] || '', ph = r[iPhone] || '', em = r[iEmail] || '';
    if (!nm) { blankName++; }
    if (!ph) { blankPhone++; }
    if (!em) { blankEmail++; }
    if (!(r[iTrade] || '')) { blankTrade++; }
    if (!(r[iScene] || '')) { blankScene++; }
    if ((r[iTrade] || '') === 'trades engineer') { genericTrade++; }
    if ((r[iScene] || '') === 'out on a job') { genericScene++; }

    if (ph) {
      if (seenPhone[ph]) { dupPhone++; if (dupPhoneEg.length < 5) { dupPhoneEg.push(nm + ' / ' + ph); } }
      else { seenPhone[ph] = true; }
    }
    var ct = r[iCert] || '';
    if (ct) {
      if (seenCert[ct]) { dupCert++; if (dupCertEg.length < 5) { dupCertEg.push(nm + ' / ' + ct); } }
      else { seenCert[ct] = true; }
    }

    bump(routes, r[iRoute]); bump(prios, r[iPrio]); bump(srcs, r[iSrc]);
    bump(dates, r[iDate]); bump(countries, r[iCountry]); bump(vers, r[iVer]);
    if ((r[iEmailable] || '') === 'TRUE') { emailableY++; }
    if ((r[iPecr] || '') === 'TRUE') { pecrY++; }
    if ((r[iComp] || '')) { withComp++; }
  }

  return [{ json: {
    sheetRange: res.range,
    headerCount: header.length,
    headerFirst5: header.slice(0, 5),
    headerLast5: header.slice(header.length - 5),
    dataRows: body.length,
    uniquePhones: Object.keys(seenPhone).length,
    duplicatePhoneRows: dupPhone,
    duplicatePhoneExamples: dupPhoneEg,
    uniqueCertNumbers: Object.keys(seenCert).length,
    duplicateCertRows: dupCert,
    duplicateCertExamples: dupCertEg,
    blanks: { name: blankName, phone: blankPhone, email: blankEmail,
              trade: blankTrade, tradeScene: blankScene },
    genericFallbacks: { trade: genericTrade, tradeScene: genericScene },
    malformedRows: { tooFewCols: shortRows, tooManyCols: longRows },
    emailableTrue: emailableY,
    pecrRiskTrue: pecrY,
    rowsWithCompetitor: withComp,
    byTemplateRoute: routes,
    byPriority: prios,
    bySource: srcs,
    byDateAdded: dates,
    byCountry: countries,
    byVerifyStatus: vers
  }}];
} catch (e) {
  return [{ json: { _error: 'Audit failed: ' + e.message } }];
}
